const icons={dashboard:'▦',accounts:'▤',payments:'⇄',ledger:'≡',health:'◇'};
const names={dashboard:'Dashboard',accounts:'Accounts',payments:'Payments',ledger:'Ledger',health:'System Health'};
const app=document.getElementById('app');
const state={page:'dashboard',concept:false,detail:null,modal:null,filter:'all',search:'',health:{phase:'checking'},apiBase:localStorage.getItem('paylab-api-base')||'',loading:false};
const examples=[{id:'PAY-000184',date:'Sep 23, 2026 · 14:32 UTC',source:'ACC-001',destination:'ACC-037',amount:'R$ 350.90',status:'SUCCEEDED'},{id:'PAY-000183',date:'Sep 23, 2026 · 14:16 UTC',source:'ACC-012',destination:'ACC-021',amount:'R$ 1,240.00',status:'FAILED'},{id:'PAY-000182',date:'Sep 23, 2026 · 13:54 UTC',source:'ACC-037',destination:'ACC-008',amount:'R$ 89.50',status:'PROCESSING'},{id:'PAY-000181',date:'Sep 23, 2026 · 13:27 UTC',source:'ACC-008',destination:'ACC-001',amount:'R$ 620.00',status:'SUCCEEDED'}];
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function badge(v){let type={SUCCEEDED:'success',FAILED:'fail',PROCESSING:'progress',CREATED:'neutral',Healthy:'success',Disconnected:'fail',Unavailable:'unavailable-badge'}[v]||'neutral';return `<span class="badge ${type}">${esc(v)}</span>`}
function nav(p){return `<button data-page="${p}" class="${state.page===p?'active':''}" aria-current="${state.page===p?'page':'false'}"><span aria-hidden="true" style="font:600 18px 'IBM Plex Mono'">${icons[p]}</span>${names[p]}</button>`}
function header(title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">Operations / ${esc(title)}</div><h1>${esc(title)}</h1><p>${desc}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`}
function conceptBanner(){return `<div class="concept-banner" role="note"><div><strong>Illustrative design · no live financial data</strong><br>These records show the intended layout only. They are not returned by the API.</div><button data-action="back-live">Return to live state</button></div>`}
function unavailable(cap,desc){return `<div class="panel unavailable"><div class="unavailable-inner"><div class="unavailable-icon" aria-hidden="true">∅</div><h2>${cap} is not available yet</h2><p>${desc}</p><div class="inline-actions"><button class="subtle-button" data-action="concept">View illustrative layout</button></div></div></div>`}
function livePage(){if(state.page==='dashboard')return header('Dashboard','Financial activity at a glance when the reporting API becomes available.')+`<div class="intro-strip"><div class="intro-cell"><div class="label">Reporting</div><div class="value muted">Unavailable</div><div class="small">Read/report API pending</div></div><div class="intro-cell"><div class="label">Payment volume</div><div class="value muted">—</div><div class="small">No endpoint available</div></div><div class="intro-cell"><div class="label">Payment count</div><div class="value muted">—</div><div class="small">No endpoint available</div></div></div>`+unavailable('Reporting','Payment volume and status summaries will appear here once the reporting API exists. No financial metrics are being estimated.');
if(state.page==='accounts')return header('Accounts','Find wallets and inspect how their balances were derived.',`<button class="primary-button" disabled title="Accounts API unavailable">Create wallet</button>`)+unavailable('Accounts API','Wallet lookup, creation, and ledger history depend on the Accounts API.');
if(state.page==='payments')return header('Payments','Inspect lifecycle outcomes and trace every successful movement to the ledger.',`<button class="primary-button" disabled title="Payments API unavailable">Create payment</button>`)+unavailable('Payments API','Payment search, creation, and details will be enabled when the Payments API is exposed.');
return header('Ledger','Immutable debit and credit evidence for financial movements.')+unavailable('Ledger API','Account entry history and transaction details require a read API. Entries cannot be edited or deleted.');}
function health(){let h=state.health;let status=h.phase==='healthy'?'Healthy':h.phase==='checking'?'Checking':'Disconnected';return header('System Health','The current live integration checks the application endpoint.',`<button class="subtle-button" data-action="refresh-health" ${h.phase==='checking'?'disabled':''}>${h.phase==='checking'?'Checking…':'Refresh health status'}</button>`)+`<div class="panel"><div class="panel-head"><div><h2>API connectivity</h2><p>GET ${esc(state.apiBase||'')}/health</p></div>${badge(status)}</div><div class="section">${h.phase==='checking'?`<div role="status" aria-live="polite"><div class="skeleton" style="width:33%"></div><div class="skeleton" style="width:55%"></div><div class="skeleton" style="width:42%"></div></div>`:h.phase==='healthy'?`<div class="health-card"><div><div class="eyebrow">Status</div><div class="health-value">${esc(h.data.status)}</div></div><div><div class="eyebrow">Application</div><div class="health-value mono">${esc(h.data.app)}</div></div><div><div class="eyebrow">Environment</div><div class="health-value mono">${esc(h.data.environment)}</div></div></div>`:`<div class="notice error" role="alert"><div class="notice-icon">!</div><div><strong>API unreachable</strong><br>${esc(h.message||'The health endpoint did not respond.')} Check the API address and try again.</div></div>`}</div></div><p class="footnote">Only application status, name, and environment are available. Component health is not inferred.</p>`}
function dashboardConcept(){return header('Dashboard','An overview of payment activity when the reporting API is available.')+conceptBanner()+`<div class="intro-strip"><div class="intro-cell"><div class="label">Payment volume · selected period</div><div class="value amount">R$ 18,420.40</div><div class="small">Illustrative</div></div><div class="intro-cell"><div class="label">Payment count</div><div class="value amount">128</div><div class="small">Illustrative</div></div><div class="intro-cell"><div class="label">Succeeded / Failed</div><div class="value amount">121 / 7</div><div class="small">Illustrative</div></div></div><div class="grid-2"><div class="panel"><div class="panel-head"><div><h2>Recent payments</h2><p>Latest activity in the selected period</p></div><button class="link-button" data-page="payments">View payments</button></div>${paymentTable(examples.slice(0,3))}</div><div class="panel"><div class="panel-head"><div><h2>System</h2><p>Live health remains separate from sample metrics</p></div></div><div class="section"><div class="notice"><div class="notice-icon">i</div><div>Check <button class="table-link" data-page="health">System Health</button> for the real API response.</div></div></div></div></div>`}
function paymentTable(rows){return `<div class="table-wrap"><table><thead><tr><th scope="col">Payment</th><th scope="col">From → To</th><th scope="col">Status</th><th scope="col" class="amount-cell">Amount</th></tr></thead><tbody>${rows.map(r=>`<tr><td><button class="table-link" data-action="payment-detail" data-id="${r.id}">${r.id}</button><div class="subid">${r.date}</div></td><td><span class="id">${r.source}</span> <span style="color:#8397a4">→</span> <span class="id">${r.destination}</span></td><td>${badge(r.status)}</td><td class="amount-cell amount">${r.amount}</td></tr>`).join('')||`<tr><td colspan="4" style="padding:32px;text-align:center;color:#9eb0bc">No payments match these filters.</td></tr>`}</tbody></table></div>`}
function accountsConcept(){if(state.detail==='account')return accountDetail();return header('Accounts','Wallet balances are derived from ledger entries.',`<button class="primary-button" data-action="create-wallet">Create wallet</button>`)+conceptBanner()+`<div class="panel"><div class="toolbar"><input aria-label="Search account identifier" placeholder="Search account ID" id="account-search"><span class="fine">Illustrative wallet list · BRL</span></div><div class="table-wrap"><table><thead><tr><th scope="col">Account</th><th scope="col">Kind</th><th scope="col">Currency</th><th scope="col" class="amount-cell">Derived balance</th></tr></thead><tbody>${[['ACC-001','R$ 2,480.10'],['ACC-037','R$ 890.25'],['ACC-012','R$ 175.00'],['ACC-021','R$ 6,200.00']].map(a=>`<tr><td><button class="table-link" data-action="account-detail" data-id="${a[0]}">${a[0]}</button></td><td>WALLET</td><td>BRL</td><td class="amount-cell amount">${a[1]}</td></tr>`).join('')}</tbody></table></div></div><p class="footnote">If the backend offers read-by-ID only, this list becomes a direct account lookup.</p>`}
function accountDetail(){return header('Account ACC-001','Wallet identity and balance evidence.',`<button class="subtle-button" data-action="accounts-list">Back to accounts</button>`)+conceptBanner()+`<div class="grid-2"><div class="panel"><div class="panel-head"><h2>Account overview</h2>${badge('WALLET')}</div><div class="section"><dl class="info-list"><div><dt>Account identifier</dt><dd class="id">ACC-001 <button class="table-link" data-action="copy" data-copy="ACC-001" aria-label="Copy account identifier">⧉</button></dd></div><div><dt>Currency</dt><dd>BRL</dd></div><div><dt>Derived balance</dt><dd class="amount">R$ 2,480.10</dd></div><div><dt>Calculation</dt><dd>Credits minus debits</dd></div></dl></div></div><div class="panel"><div class="panel-head"><h2>Balance provenance</h2></div><div class="section"><div class="notice"><div class="notice-icon">≡</div><div>This balance is computed from immutable Ledger Entries. It is not directly editable.</div></div></div></div></div><div class="panel" style="margin-top:20px"><div class="panel-head"><div><h2>Ledger entry history</h2><p>Newest entries first</p></div><button class="subtle-button" data-page="ledger">View ledger</button></div><div class="table-wrap"><table><thead><tr><th>Entry</th><th>Transaction</th><th>Direction</th><th>Created</th><th class="amount-cell">Amount</th></tr></thead><tbody><tr><td class="id">LE-000368</td><td class="id">LT-000184</td><td><span class="direction debit">DEBIT</span></td><td>Sep 23, 2026 · 14:32 UTC</td><td class="amount-cell amount">R$ 350.90</td></tr><tr><td class="id">LE-000362</td><td class="id">LT-000181</td><td><span class="direction credit">CREDIT</span></td><td>Sep 23, 2026 · 13:27 UTC</td><td class="amount-cell amount">R$ 620.00</td></tr></tbody></table></div><div class="section"><button class="subtle-button" disabled>Load more</button><span class="fine" style="margin-left:12px">Cursor pagination concept</span></div></div>`}
function paymentsConcept(){if(state.detail==='payment')return paymentDetail();if(state.detail==='create')return createPayment();let rows=examples.filter(r=>(state.filter==='all'||r.status===state.filter)&&(!state.search||[r.id,r.source,r.destination].some(v=>v.toLowerCase().includes(state.search.toLowerCase()))));return header('Payments','Inspect outcomes and trace successful payments to ledger evidence.',`<button class="primary-button" data-action="create-payment">Create payment</button>`)+conceptBanner()+`<div class="panel"><div class="toolbar"><input id="payment-search" aria-label="Search payment or account ID" placeholder="Payment or account ID" value="${esc(state.search)}"><select id="payment-filter" aria-label="Filter by status"><option value="all" ${state.filter==='all'?'selected':''}>All statuses</option>${['CREATED','PROCESSING','SUCCEEDED','FAILED'].map(v=>`<option ${state.filter===v?'selected':''}>${v}</option>`).join('')}</select><span class="fine">Most recent first · cursor pagination</span></div>${paymentTable(rows)}<div class="section" style="border-top:1px solid #30404c"><button class="subtle-button" disabled>Load more</button><span class="fine" style="margin-left:12px">End of illustrative records</span></div></div>`}
function paymentDetail(){let p=examples.find(x=>x.id===state.selectedPayment)||examples[0],s=p.status,success=s==='SUCCEEDED';return header(`Payment ${p.id}`,'Intent, outcome, accounts, and accounting evidence.',`<button class="subtle-button" data-action="payments-list">Back to payments</button>`)+conceptBanner()+`<div class="grid-2"><div class="panel"><div class="panel-head"><h2>Payment outcome</h2>${badge(s)}</div><div class="section"><div class="eyebrow">Amount</div><div class="amount" style="font-size:36px;letter-spacing:-.05em;margin:8px 0 25px">${p.amount}</div><dl class="info-list"><div><dt>Payment ID</dt><dd class="id">${p.id} <button class="table-link" data-action="copy" data-copy="${p.id}" aria-label="Copy payment ID">⧉</button></dd></div><div><dt>Created</dt><dd>${p.date}</dd></div><div><dt>Source Account</dt><dd class="id">${p.source}</dd></div><div><dt>Destination Account</dt><dd class="id">${p.destination}</dd></div>${s==='FAILED'?'<div><dt>Failure reason</dt><dd>INSUFFICIENT_FUNDS</dd></div>':''}</dl><div class="timeline" aria-label="Payment lifecycle"><div class="step done">CREATED</div><div class="step ${s==='CREATED'?'current':'done'}">PROCESSING</div><div class="step ${success?'done':s==='FAILED'?'current':''}">${s==='FAILED'?'FAILED':'SUCCEEDED'}</div></div><div class="fine">Stages only; transition timestamps are not available.</div></div></div><div class="panel"><div class="panel-head"><h2>Ledger evidence</h2></div><div class="section">${success?`<div class="eyebrow">Ledger Transaction</div><div class="id" style="margin:10px 0 24px">LT-000184</div><div class="entry-row"><span class="direction debit">DEBIT</span><span class="id">${p.source}</span><span class="amount">${p.amount}</span></div><div class="entry-row"><span class="direction credit">CREDIT</span><span class="id">${p.destination}</span><span class="amount">${p.amount}</span></div><div class="balance-check"><span>Balanced entries</span><span class="mono">Δ 0.00 BRL</span></div><button class="link-button" style="margin-top:23px" data-page="ledger">Inspect ledger</button>`:`<div class="notice ${s==='FAILED'?'warning':''}"><div class="notice-icon">${s==='FAILED'?'!':'i'}</div><div>${s==='FAILED'?'Payment failed: insufficient funds. No Ledger Transaction was created.':'No Ledger Transaction is linked to this Payment state.'}</div></div>`}</div></div></div>`}
function createPayment(){return header('Create Payment','Transfer BRL between two wallets.',`<button class="subtle-button" data-action="payments-list">Back to payments</button>`)+conceptBanner()+`<div class="panel" style="max-width:760px"><div class="panel-head"><div><h2>Payment details</h2><p>Fields and validation are illustrative. Submission needs the Payments API.</p></div></div><form class="section" id="payment-form" novalidate><div class="form-grid"><div class="field"><label for="source">Source Account</label><input id="source" required placeholder="Account ID, e.g. ACC-001"><span class="field-error" id="source-error"></span></div><div class="field"><label for="destination">Destination Account</label><input id="destination" required placeholder="Account ID, e.g. ACC-037"><span class="field-error" id="destination-error"></span></div><div class="field"><label for="amount">Amount (BRL)</label><input id="amount" required inputmode="decimal" placeholder="0.00"><span class="field-error" id="amount-error"></span></div><div class="field"><label for="key">Idempotency Key</label><input id="key" readonly value="Generated when the API becomes available"><span class="fine">Technical metadata; generated client-side per attempt.</span></div></div><div class="form-foot"><div class="fine">A failed Payment is a business outcome; a network error is a request failure.</div><button class="primary-button" type="submit">Review fields</button></div></form></div>`}
function ledgerConcept(){return header('Ledger','Every successful payment is supported by immutable, balanced entries.')+conceptBanner()+`<div class="notice" style="margin-bottom:20px"><div class="notice-icon">≡</div><div><strong>Accounting rule</strong><br>Direction is separate from a positive amount. For each Ledger Transaction, total debits equal total credits. Entries cannot be edited or deleted.</div></div><div class="panel"><div class="panel-head"><div><h2>Ledger Transactions</h2><p>Grouped by transaction identifier</p></div><span class="fine">Illustrative</span></div>${[['LT-000184','PAY-000184','ACC-001','ACC-037','R$ 350.90'],['LT-000181','PAY-000181','ACC-008','ACC-001','R$ 620.00']].map(g=>`<div class="entry-group"><div class="entry-title"><div><span class="id">${g[0]}</span> <span style="margin:0 8px">·</span> ${g[1]}</div><span>Sep 23, 2026 · UTC</span></div><div class="entry-row"><span class="direction debit">DEBIT</span><span class="id">${g[2]}</span><span class="amount">${g[4]}</span></div><div class="entry-row"><span class="direction credit">CREDIT</span><span class="id">${g[3]}</span><span class="amount">${g[4]}</span></div><div class="balance-check"><span>Balanced transaction</span><span class="mono">Δ 0.00 BRL</span></div></div>`).join('')}</div>`}
function modal(){if(!state.modal)return '';let title=state.modal==='states'?'Interface states':'API connection';let body=state.modal==='settings'?`<p class="fine" style="margin-top:0">Enter the base URL of a PayLab API that exposes GET /health. The address is stored only in this browser. The API must allow requests from this site's origin.</p><div class="field"><label for="api-base">API base URL</label><input id="api-base" type="url" placeholder="https://api.example.com" value="${esc(state.apiBase)}"><span class="fine">Leave empty to use this site's origin.</span></div><div class="form-foot"><span></span><button class="primary-button" data-action="save-api">Save and check</button></div>`:`<p class="fine" style="margin-top:0">Reusable patterns for the console. The examples below describe behavior; they are not API results.</p><div class="state-gallery">${[['Loading','Page skeleton keeps table structure visible. Refresh keeps existing data on screen.'],['Empty','No records exist. State the scope and offer the next valid action.'],['Filtered · no results','No results match these filters. Offer a clear reset.'],['API error','Show the request failure and a retry action.'],['Disconnected','API unreachable. Preserve context and expose connection settings.'],['Unauthorized','Access required. Do not imply that the requested record is missing.'],['Not found','The requested identifier was not found. Return to the relevant list.'],['Capability unavailable','The backend operation has not been exposed yet. No placeholder data.'],['Validation error','Keep field values and attach a specific error to the field.'],['Business failure','Payment failed: insufficient funds. No ledger entries were created.']].map(([a,b])=>`<div class="state-card"><h3>${a}</h3><p>${b}</p></div>`).join('')}</div><div class="divider"></div><h3 style="font-size:15px">Status vocabulary</h3><div style="display:flex;gap:8px;flex-wrap:wrap">${['CREATED','PROCESSING','SUCCEEDED','FAILED','Healthy','Disconnected','Unavailable'].map(badge).join('')}</div>`;return `<div class="modal-backdrop" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-body">${body}</div></div></div>`}
function render(){let status=state.health.phase==='healthy'?'Healthy':state.health.phase==='checking'?'Checking':'Disconnected';app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="mark">P</div><div><div class="brand-name">PayLab</div><div class="brand-sub">Operational Console</div></div></div><div class="nav-label">Workspace</div><nav class="nav" aria-label="Primary">${Object.keys(names).map(nav).join('')}</nav><div class="side-bottom"><div class="eyebrow">Financial core</div><p>Payments describe intent. Ledger entries provide the accounting evidence.</p></div></aside><main class="workspace"><div class="topbar"><div class="crumb">PayLab <span style="color:#566a78;margin:0 10px">/</span> <strong>${names[state.page]}</strong></div><div class="mobilebar"><div class="mark" style="width:29px;height:29px;font-size:15px">P</div><span class="brand-name">PayLab</span></div><div class="top-actions"><span class="status-line ${state.health.phase==='healthy'?'ok':state.health.phase==='error'?'bad':''}"><span class="status-dot"></span>API ${status.toLowerCase()}</span><button class="link-button" data-action="settings">API settings</button><button class="link-button" data-action="states">UI states</button></div></div><nav class="mobile-nav" aria-label="Primary">${Object.keys(names).map(p=>`<button data-page="${p}" class="${state.page===p?'active':''}" aria-current="${state.page===p?'page':'false'}">${names[p]}</button>`).join('')}</nav><div class="mobile-tools"><button data-action="settings">API settings</button><button data-action="states">UI states</button></div><div class="content">${state.page==='health'?health():state.concept?({dashboard:dashboardConcept,accounts:accountsConcept,payments:paymentsConcept,ledger:ledgerConcept}[state.page]||health)():livePage()}</div></main></div>${modal()}`;document.title=`${names[state.page]} · PayLab`;}
function go(p){state.page=p;state.detail=null;state.search='';state.filter='all';state.concept=false;location.hash=p;render();window.scrollTo(0,0)}
async function checkHealth(){state.health={phase:'checking'};render();let base=state.apiBase.replace(/\/$/,'');let ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),7000);try{let res=await fetch(`${base}/health`,{signal:ctrl.signal,cache:'no-store',headers:{Accept:'application/json'}});if(!res.ok)throw Error(`HTTP ${res.status}`);let data=await res.json();if(!data||typeof data.status!=='string'||typeof data.app!=='string'||typeof data.environment!=='string')throw Error('Unexpected health response');state.health={phase:'healthy',data};}catch(e){state.health={phase:'error',message:e.name==='AbortError'?'The request timed out.':e.message};}finally{clearTimeout(timer);render()}}
function toast(msg){let old=document.querySelector('.toast');old?.remove();let el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=msg;document.body.append(el);setTimeout(()=>el.remove(),3000)}
document.addEventListener('click',async e=>{let p=e.target.closest('[data-page]');if(p){go(p.dataset.page);return}let el=e.target.closest('[data-action]');if(!el)return;let a=el.dataset.action;if(a==='close-modal'&&e.target!==el&&e.target.closest('.modal')&&!e.target.closest('.modal-header button'))return;if(a==='concept'){state.concept=true;state.detail=null;render()}if(a==='back-live'){state.concept=false;state.detail=null;render()}if(a==='refresh-health')checkHealth();if(a==='settings'||a==='states'){state.modal=a;render();setTimeout(()=>document.querySelector('.modal-header button')?.focus(),0)}if(a==='close-modal'){state.modal=null;render()}if(a==='save-api'){let v=document.querySelector('#api-base').value.trim();if(v&&(!/^https?:\/\//i.test(v)||!URL.canParse(v))){toast('Enter a valid HTTP or HTTPS URL.');return}state.apiBase=v;localStorage.setItem('paylab-api-base',v);state.modal=null;checkHealth()}if(a==='account-detail'){state.detail='account';render();window.scrollTo(0,0)}if(a==='payment-detail'){state.selectedPayment=el.dataset.id;state.detail='payment';render();window.scrollTo(0,0)}if(a==='create-payment'){state.detail='create';render()}if(a==='accounts-list'||a==='payments-list'){state.detail=null;render()}if(a==='create-wallet')toast('Wallet creation requires the Accounts API.');if(a==='copy'){try{await navigator.clipboard.writeText(el.dataset.copy);toast('Identifier copied.')}catch{toast('Copy unavailable in this browser.')}}});
document.addEventListener('input',e=>{if(e.target.id==='payment-search'){state.search=e.target.value;let pos=e.target.selectionStart;render();let input=document.querySelector('#payment-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='account-search'){let q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.id==='payment-filter'){state.filter=e.target.value;render()}});
document.addEventListener('submit',e=>{if(e.target.id!=='payment-form')return;e.preventDefault();let source=document.querySelector('#source'),destination=document.querySelector('#destination'),amount=document.querySelector('#amount');let errors={source:source.value.trim()?'':'Enter a source Account ID.',destination:destination.value.trim()?'':'Enter a destination Account ID.',amount:/^\d+(?:[.,]\d{1,2})?$/.test(amount.value.trim())&&Number(amount.value.replace(',','.'))>0?'':'Enter a positive amount with up to two decimal places.'};if(!errors.source&&!errors.destination&&source.value.trim()===destination.value.trim())errors.destination='Use a different destination Account.';for(let k of Object.keys(errors)){document.querySelector(`#${k}-error`).textContent=errors[k];document.querySelector(`#${k}`).setAttribute('aria-invalid',!!errors[k]);document.querySelector(`#${k}`).setAttribute('aria-describedby',`${k}-error`)}if(Object.values(errors).some(Boolean)){document.querySelector('[aria-invalid="true"]')?.focus();return}toast('Fields valid. Payment submission requires the Payments API.')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal){state.modal=null;render()}});
let initial=location.hash.slice(1);if(names[initial])state.page=initial;render();checkHealth();
